function p_simulates(a, b, N, Kmax):
    for k in 1 .. Kmax:
        ok = true
        for n in 0 .. N-1:
            f_of_bn = (b(n) + 2) ^ k        # candidate poly blow-up
            if a(n) > f_of_bn:
                ok = false; break
        if ok: return k                     # witness exponent found
    return NONE                             # no poly bound up to Kmax/N

