from typing import List, Tuple

def v2(n: int) -> int:
    if n == 0:
        return 0
    c = 0
    while n % 2 == 0:
        n //= 2
        c += 1
    return c

def incomparability_witness(i: int, j: int, f0: int) -> Tuple[int, int]:
    assert i != j, 'spike systems are only incomparable for distinct indices'
    n = (2 ** i) * (2 * (f0 + 1) + 1)
    return n, v2(n)  # v2(n) == i, and n > f0, and cost there is 2**n

def demo_witnesses() -> List[str]:
    out: List[str] = []
    for (i, j) in [(0, 1), (1, 2), (0, 3), (2, 5)]:
        n, val = incomparability_witness(i, j, f0=1000)
        out.append(f'i={i}, j={j}: n={n}, v2(n)={val}, n>1000 -> 2^n defeats f(0)')
    return out

if __name__ == '__main__':
    print('\n'.join(demo_witnesses()))
